// 見つけた結果は body へ覚えるので、毎フレームの querySelector にはならない。
const RHYTHM_SLIDE_GROUP_ATTRS=Object.freeze({fill:'data-rhythm-slide-fill',edge:'data-rhythm-slide-edge-layer',marks:'data-rhythm-slide-marks'});
