  const attr=RHYTHM_SLIDE_GROUP_ATTRS[kind]||RHYTHM_SLIDE_GROUP_ATTRS.fill;
  const cacheKey=RHYTHM_SLIDE_GROUP_CACHE_KEYS[kind]||RHYTHM_SLIDE_GROUP_CACHE_KEYS.fill;
